package local.skyfamily;
import java.io.*;import java.util.*;import java.util.zip.*;import org.xmlpull.v1.XmlPullParser;import android.text.Html;
final class BookData {
 String title="Book",author="";byte[] cover;ArrayList<String> chapters=new ArrayList<>();
 static byte[] read(InputStream input,int max)throws Exception{try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("Book resource exceeds size limit");out.write(b,0,n);}return out.toByteArray();}}
 static XmlPullParser parser(byte[] bytes)throws Exception{XmlPullParser p=android.util.Xml.newPullParser();p.setFeature(XmlPullParser.FEATURE_PROCESS_NAMESPACES,true);p.setInput(new ByteArrayInputStream(bytes),null);return p;}
 static byte[] entry(ZipFile zip,String path,int max)throws Exception{ZipEntry e=zip.getEntry(path);if(e==null||e.isDirectory()||e.getSize()>max)throw new IOException("Missing or oversized EPUB resource");return read(zip.getInputStream(e),max);}
 static String path(String base,String href)throws Exception{java.net.URI b=new java.net.URI(null,null,base,null);java.net.URI u=b.resolve(href.replace(" ","%20")).normalize();if(u.getScheme()!=null)throw new IOException("Remote EPUB resources are not imported");String p=u.getPath();while(p.startsWith("/"))p=p.substring(1);if(p.startsWith("../"))throw new IOException("Invalid EPUB path");return p;}
 static String plain(String html){return Html.fromHtml(html.replaceAll("(?is)<script[^>]*>.*?</script>","").replaceAll("(?is)<style[^>]*>.*?</style>","")).toString().trim();}
 static BookData load(File file)throws Exception{BookData book=new BookData();if(file.getName().endsWith(".txt")){String value=new String(read(new FileInputStream(file),8000000),"UTF-8");if(value.indexOf(0)>=0)throw new IOException("Not a supported UTF-8 text book");for(int start=0;start<value.length();start+=60000)book.chapters.add(value.substring(start,Math.min(value.length(),start+60000)));if(book.chapters.isEmpty())book.chapters.add("Empty text file");return book;}try(ZipFile zip=new ZipFile(file)){int entries=0;long expanded=0;Enumeration<? extends ZipEntry> all=zip.entries();while(all.hasMoreElements()){ZipEntry e=all.nextElement();entries++;expanded+=Math.max(0,e.getSize());if(entries>3000||expanded>100000000)throw new IOException("EPUB archive exceeds import limits");}if(zip.getEntry("META-INF/encryption.xml")!=null)throw new IOException("Encrypted EPUB resources are not supported");XmlPullParser container=parser(entry(zip,"META-INF/container.xml",1000000));String opf=null;for(int event=container.getEventType();event!=XmlPullParser.END_DOCUMENT;event=container.next())if(event==XmlPullParser.START_TAG&&container.getName().equals("rootfile")){opf=container.getAttributeValue(null,"full-path");break;}if(opf==null)throw new IOException("EPUB package missing");String base=opf.substring(0,opf.lastIndexOf('/')+1);XmlPullParser p=parser(entry(zip,opf,2000000));HashMap<String,String> manifest=new HashMap<>();ArrayList<String> spine=new ArrayList<>();String coverId="",coverPath="";for(int event=p.getEventType();event!=XmlPullParser.END_DOCUMENT;event=p.next()){if(event!=XmlPullParser.START_TAG)continue;String name=p.getName();if(name.equals("title"))book.title=p.nextText();else if(name.equals("creator"))book.author=p.nextText();else if(name.equals("meta")&&"cover".equals(p.getAttributeValue(null,"name")))coverId=p.getAttributeValue(null,"content");else if(name.equals("item")){String id=p.getAttributeValue(null,"id"),href=p.getAttributeValue(null,"href"),properties=p.getAttributeValue(null,"properties");if(id!=null&&href!=null){String location=path(base,href);manifest.put(id,location);if(properties!=null&&properties.contains("cover-image"))coverPath=location;}}else if(name.equals("itemref")&&!"no".equals(p.getAttributeValue(null,"linear"))){String id=p.getAttributeValue(null,"idref");if(id!=null)spine.add(id);}}if(coverPath.isEmpty()&&manifest.containsKey(coverId))coverPath=manifest.get(coverId);if(!coverPath.isEmpty())try{book.cover=entry(zip,coverPath,8000000);}catch(Exception ignored){}int chars=0;for(String id:spine){String href=manifest.get(id);if(href==null)continue;String chapter=plain(new String(entry(zip,href,2000000),"UTF-8"));chars+=chapter.length();if(chars>4000000)throw new IOException("EPUB text exceeds reader limit");if(!chapter.isEmpty())book.chapters.add(chapter);}if(book.chapters.isEmpty())throw new IOException("No readable EPUB text in the spine");return book;}}
}
